st Ratio\":\"150,000:1\",\"Operating System\":\"Android TV 11.0\",\"Speakers\":\"Dual 10W Harman Kardon\"},\"reviews\":[{\"id\":106,\"name\":\"Sam Altman\",\"rating\":5,\"date\":\"2026-07-02\",\"comment\":\"Incredible picture quality, even with some ambient light in the room.\"}],\"isFeatured\":false,\"isBestSeller\":false,\"isNewArrival\":false},{\"id\":5,\"name\":\"Classic Leather Minimalist Sneakers\",\"brand\":\"FootWear\",\"category\":\"fashion\",\"price\":129.99,\"discountPrice\":110,\"discountPercentage\":15,\"rating\":4.9,\"reviewsCount\":204,\"stock\":14,\"images\":[\"https://images.unsplash.com/photo-1549298916-b41d501d3772?w=800&auto=format&fit=crop&q=80\",\"https://images.unsplash.com/photo-1595950653106-6c9ebd614d3a?w=800&auto=format&fit=crop&q=80\",\"https://images.unsplash.com/photo-1606107557195-0e29a4b5b4aa?w=800&auto=format&fit=crop&q=80\"],\"colors\":[\"#FFFFFF\",\"#E2E8F0\",\"#2D3748\"],\"sizes\":[\"7\",\"8\",\"9\",\"10\",\"11\"],\"description\":\"Crafted from full-grain Italian leather, our classic minimalist sneakers fit any setting from boardroom meetings to casual weekends. Breathable calfskin lining and stitched rubber cupsole guarantee long-lasting durability and comfort.\",\"specs\":{\"Upper Material\":\"Premium Italian Full-Grain Leather\",\"Lining\":\"Breathable Calfskin\",\"Sole\":\"100% Margom Rubber Cupsole\",\"Country of Origin\":\"Made in Italy\",\"Style\":\"Low-top dress sneaker\"},\"reviews\":[{\"id\":107,\"name\":\"Marcus V.\",\"rating\":5,\"date\":\"2026-07-28\",\"comment\":\"Sleek, high quality, goes with everything. Standard fit.\"}],\"isFeatured\":true,\"isBestSeller\":true,\"isNewArrival\":false},{\"id\":6,\"name\":\"Premium Wool Blend Double-Breasted Coat\",\"brand\":\"AuraStyle\",\"category\":\"fashion\",\"price\":249.99,\"discountPrice\":249.99,\"discountPercentage\":0,\"rating\":4.7,\"reviewsCount\":78,\"stock\":6,\"images\":[\"https://images.unsplash.com/photo-1539571696357-5a69c17a67c6?w=800&auto=format&fit=crop&q=80\"