raStyle\",\"category\":\"fashion\",\"price\":119.99,\"discountPrice\":99.99,\"discountPercentage\":17,\"rating\":4.8,\"reviewsCount\":88,\"stock\":12,\"images\":[\"https://images.unsplash.com/photo-1548036328-c9fa89d128fa?w=800&auto=format&fit=crop&q=80\",\"https://images.unsplash.com/photo-1598532163257-ae3c6b2524b6?w=800&auto=format&fit=crop&q=80\"],\"colors\":[\"#8C7853\",\"#000000\"],\"sizes\":[\"One Size\"],\"description\":\"A stylish, spacious messenger bag for work or school. Crafted from water-resistant, cruelty-free vegan leather, it includes a padded sleeve for up to a 15-inch laptop and multi-compartment organizers.\",\"specs\":{\"Material\":\"Premium PU Vegan Leather\",\"Hardware\":\"Brushed Gunmetal Alloy\",\"Laptop Compartment\":\"Padded sleeve up to 15.6\\\"\",\"Dimensions\":\"15\\\" x 11.5\\\" x 3.5\\\"\"},\"reviews\":[{\"id\":110,\"name\":\"Olivia K.\",\"rating\":5,\"date\":\"2026-07-10\",\"comment\":\"Extremely professional bag. Soft texture, looks like real leather.\"}],\"isFeatured\":true,\"isBestSeller\":false,\"isNewArrival\":false},{\"id\":9,\"name\":\"Nordic Oak Minimalist Lounge Chair\",\"brand\":\"NordicLiving\",\"category\":\"home-decor\",\"price\":499.99,\"discountPrice\":429.99,\"discountPercentage\":14,\"rating\":4.9,\"reviewsCount\":38,\"stock\":4,\"images\":[\"https://images.unsplash.com/photo-1567538096630-e0c55bd6374c?w=800&auto=format&fit=crop&q=80\",\"https://images.unsplash.com/photo-1592078615290-033ee584e267?w=800&auto=format&fit=crop&q=80\"],\"colors\":[\"#E2E8F0\",\"#EDF2F7\",\"#CBD5E0\"],\"sizes\":[\"Standard\"],\"description\":\"Bring clean lines and warmth to your room. Crafted from FSC-certified solid European oak and upholstered in a luxurious, durable wool blend, the Nordic Oak Lounge Chair is designed for maximum relaxation and timeless appeal.\",\"specs\":{\"Frame Material\":\"FSC Solid European Oak\",\"Upholstery\":\"70% Wool, 30% Linen Blend\",\"Weight Capacity\":\"150 kg (330 lbs)\",\"Dimensions\":\"78cm H x 70cm W x 75cm D\",\"Assembly\":\"None required\"},\"reviews\":[{\"id\":111,\"name\":\"Lucas H.\",\"rating\":5,\"date\":\"2026-07-22\",\"comment\":\"Exquisite craftsmanship. Beautiful wood grain. Very comfortable lounge angle.\"}],\"isFeatured\":true,\"isBestSeller\":true,\"isNewArrival\":false},{\"id\":10,\"name\":\"AromaTherapy Ceramic Ultrasonic Humidifier\",\"brand\":\"AromaCo\",\"category\":\"home-decor\",\"price\":69.99,\"discountPrice\":59.99,\"discountPercentage\":14,\"rating\":4.6,\"reviewsCount\":160,\"stock\":25,\"images\":[\"https://images.unsplash.com/photo-1602928321679-560bb453f190?w=800&auto=format&fit=crop&q=80\",\"https://images.unsplash.com/photo-1519183071298-a2962feb14f4?w=800&auto=format&fit=crop&q=80\"],\"colors\":[\"#FFFFFF\",\"#1A202C\"],\"sizes\":[\"150ml\",\"300ml\"],\"description\":\"Transform your room into a relaxing spa. Made from hand-crafted matte ceramic, this ultrasonic diffuser humidifies air while circulating dry mist with essential oils. Featuring a warm ambient glow.\",\"specs\":{\"Material\":\"Handcrafted Ceramic Top, BPA-free Plastic Reservoir\",\"Mist Output\":\"Up to 7 hours runtime (Continuous)\",\"Coverage\":\"Up to 500 sq ft\",\"Safety Features\":\"Auto shut-off when water runs out\",\"Light Settings\":\"Dim, Bright, Breathing light\"},\"reviews\":[{\"id\":112,\"name\":\"Nadia R.\",\"rating\":5,\"date\":\"2026-07-29\",\"comment\":\"Looks gorgeous on my nightstand. Whisper quiet, highly recommend.\"}],\"isFeatured\":false,\"isBestSeller\":false,\"isNewArrival\":true},{\"id\":11,\"name\":\"Minimalist Dimmable Arch Floor Lamp\",\"brand\":\"NordicLiving\",\"category\":\"home-decor\",\"price\":189.99,\"discountPrice\":169.99,\"discountPercentage\":11,\"rating\":4.7,\"reviewsCount\":54,\"stock\":9,\"images\":[\"https://images.unsplash.com/photo-1507473885765-e6ed057f782c?w=800&auto=format&fit=crop&q=80\",\"https://images.unsplash.com/photo-1513694203232-719a280e022f?w=800&auto=format&fit=crop&q=80\"],\"colors\":[\"#000000\",\"#D69E2E